QString featureName(const FitCalibrationSession&session){const auto*e=session.hasFineExperiment?&session.fineExperiment:(session.hasCoarseExperiment?&session.coarseExperiment:nullptr);if(!e)return QStringLiteral("Empty feature");QString name;if(e->featureFamily==QStringLiteral("StandardStud"))name=e->correctionDimension==FitCorrectionDimension::Height?QStringLiteral("Stud Height"):QStringLiteral("Stud OD");else if(e->featureFamily==QStringLiteral("StudReceivingClutch"))name=QStringLiteral("Receiving Clutch");else if(e->featureFamily==QStringLiteral("FrictionlessTechnicPin"))name=QStringLiteral("Frictionless Technic Pin");else if(e->featureFamily==QStringLiteral("FrictionTechnicPin"))name=QStringLiteral("Friction Technic Pin");else if(e->featureFamily==QStringLiteral("TechnicAxle"))name=QStringLiteral("Technic Axle");else if(e->featureFamily==QStringLiteral("TechnicAxleHole"))name=QStringLiteral("Technic Axle Hole");else name=QStringLiteral("Technic Hole");if(session.process.actualPrintedOrientation==FitPrintedOrientation::FeatureAxisParallelToBuildPlate)name+=QStringLiteral(" — Parallel");else if(session.process.actualPrintedOrientation==FitPrintedOrientation::FeatureAxisPerpendicularToBuildPlate)name+=QStringLiteral(" — Perpendicular");return name;}
