void FitCalibrationDialog::createSelectedCalibration(){createCalibration(FitCalibrationFamily(m_newFamily->currentData().toInt()));}
void FitCalibrationDialog::createCalibration(FitCalibrationFamily family){switch(family){case FitCalibrationFamily::TechnicHole:newTechnicCalibration();break;case FitCalibrationFamily::StandardStud:newStudCalibration();break;case FitCalibrationFamily::StudReceivingClutch:newReceivingClutchCalibration();break;case FitCalibrationFamily::FrictionlessTechnicPin:newFrictionlessPinCalibration();break;case FitCalibrationFamily::FrictionTechnicPin:newFrictionPinCalibration();break;case FitCalibrationFamily::TechnicAxle:newTechnicAxleCalibration();break;case FitCalibrationFamily::TechnicAxleHole:newTechnicAxleHoleCalibration();break;}}
FitCalibrationExperiment* FitCalibrationDialog::activeExperiment(){if(m_tabs->currentIndex()==0)return m_session.hasCoarseExperiment?&m_session.coarseExperiment:nullptr;return m_session.hasFineExperiment?&m_session.fineExperiment:nullptr;}
QTableWidget* FitCalibrationDialog::activeTable()const{return m_tabs->currentIndex()==0?m_coarseTable:m_fineTable;}
void FitCalibrationDialog::readProcess(){if(m_loading)return;if(m_featureIndex>=0&&m_featureIndex<m_workspace.featureSessions.size())m_workspace.featureSessions[m_featureIndex]=m_session;const auto orientation=FitPrintedOrientation(m_orientation->currentData().toInt());const QString orientationNotes=m_orientationNotes->text();for(auto& feature:m_workspace.featureSessions){feature.process.printerIdentity=m_printer->text().trimmed();feature.process.materialIdentity=m_material->text().trimmed();feature.process.profileName=m_profile->text().trimmed();feature.process.hasNozzleDiameter=true;feature.process.nozzleDiameterMillimetres=m_nozzle->value();feature.process.hasLayerHeight=true;feature.process.layerHeightMillimetres=m_layer->value();feature.process.dimensionalCompensationNotes=m_compensationNotes->text();if(feature.sessionIdentity==m_session.sessionIdentity){feature.process.actualPrintedOrientation=orientation;feature.process.orientationNotes=orientationNotes;}if(feature.hasCoarseExperiment)feature.coarseExperiment.process=feature.process;if(feature.hasFineExperiment)feature.fineExperiment.process=feature.process;}if(m_featureIndex>=0&&m_featureIndex<m_workspace.featureSessions.size())m_session=m_workspace.featureSessions[m_featureIndex];if(!m_workspace.featureSessions.isEmpty()){m_workspace.process=m_workspace.featureSessions.front().process;m_workspace.process.actualPrintedOrientation=FitPrintedOrientation::Unknown;m_workspace.process.orientationNotes.clear();m_workspace.identity=FitCalibrationLibrary::manufacturingContextFingerprint(m_workspace.process);m_workspace.displayName=FitCalibrationLibrary::workspaceDisplayName(m_workspace.process);}}
void FitCalibrationDialog::refreshTable(QTableWidget*t,const FitCalibrationExperiment*e){const int selectedRow=t->currentRow();t->setRowCount(e?e->candidates.size():0);if(!e)return;const bool height=e->correctionDimension==FitCorrectionDimension::Height;const bool axle=e->featureFamily==QStringLiteral("TechnicAxle")||e->featureFamily==QStringLiteral("TechnicAxleHole");t->setHorizontalHeaderItem(1,new QTableWidgetItem(height?"Height Correction (mm)":axle?"Tip-to-Tip Correction (mm)":"Diameter Correction (mm)"));t->setHorizontalHeaderItem(2,new QTableWidgetItem(height?"Height (mm)":axle?"Tip-to-Tip (mm)":"Diameter (mm)"));for(int r=0;r<e->candidates.size();++r){const auto&c=e->candidates[r];t->setItem(r,0,new QTableWidgetItem(QString::number(c.index)));t->setItem(r,1,new QTableWidgetItem(QString::number(FitCalibrationEvidencePolicy::candidateCorrection(*e,c),'f',3)));t->setItem(r,2,new QTableWidgetItem(QString::number(FitCalibrationEvidencePolicy::candidateFunctionalDimension(*e,c),'f',3)));t->setItem(r,3,new QTableWidgetItem(QString::number(FitCalibrationEvidencePolicy::observationCount(c))));t->setItem(r,4,new QTableWidgetItem(FitCalibrationEvidencePolicy::observationProgressText(*e,c)));t->setItem(r,5,new QTableWidgetItem(c.observations.isEmpty()?QString():resultText(c.observations.back().result)));t->setItem(r,6,new QTableWidgetItem(c.index==e->preferredCandidateIndex?"Yes":""));}if(selectedRow>=0&&selectedRow<t->rowCount())t->selectRow(selectedRow);}
void FitCalibrationDialog::refresh(){refreshTable(m_coarseTable,m_session.hasCoarseExperiment?&m_session.coarseExperiment:nullptr);refreshTable(m_fineTable,m_session.hasFineExperiment?&m_session.fineExperiment:nullptr);m_tabs->setTabEnabled(0,m_session.hasCoarseExperiment);m_tabs->setTabEnabled(1,m_session.hasFineExperiment);m_identity->setText(m_workspace.featureSessions.isEmpty()?QStringLiteral("No calibration workspace loaded"):QStringLiteral("%1 — %2").arg(FitCalibrationLibrary::workspaceDisplayName(m_session.process),featureName(m_session)));m_coarseContext->setText(m_session.hasCoarseExperiment?QStringLiteral("Artifact: %1").arg(m_session.coarseExperiment.artifactIdentity):QStringLiteral("No coarse search is present in this legacy session."));m_fineContext->setText(m_session.hasFineExperiment?QStringLiteral("Artifact: %1 — Parent: %2 — Center: %3 mm").arg(m_session.fineExperiment.artifactIdentity,m_session.fineExperiment.parentArtifactIdentity).arg(FitCalibrationEvidencePolicy::candidateCorrection(m_session.fineExperiment,m_session.fineExperiment.candidates[m_session.fineExperiment.candidates.size()/2]),0,'f',3):QStringLiteral("Generate a fine search or direct verification artifact from a selected candidate."));m_save->setEnabled(m_session.hasCoarseExperiment||m_session.hasFineExperiment);auto*e=activeExperiment();m_generate->setEnabled(e&&FitCalibrationEvidencePolicy::continuationAvailable(*e));QString verificationReason;const bool ready=e&&e->state!=FitEvidenceState::Verified&&FitCalibrationEvidencePolicy::canMarkVerified(*e,&verificationReason);m_verify->setEnabled(ready);m_verify->setText(e&&e->state==FitEvidenceState::Verified?QStringLiteral("Verified"):QStringLiteral("Mark Verified"));m_verify->setToolTip(ready?QStringLiteral("All verification requirements are satisfied. Click to explicitly accept this calibration. Fine Search remains optional."):verificationReason);updateGuidance();}
void FitCalibrationDialog::updateGuidance(){const auto*e=activeExperiment();QString text=e?FitCalibrationEvidencePolicy::guidanceText(*e):QStringLiteral("Load a calibration session to begin.");if(e&&e->state!=FitEvidenceState::Verified){QString reason;if(FitCalibrationEvidencePolicy::canMarkVerified(*e,&reason))text=QStringLiteral("Calibration evidence is sufficient. Mark Verified is available; Fine Search or additional verification is optional.");else if(e->preferredCandidateIndex>0)text=QStringLiteral("Mark Verified unavailable: %1").arg(reason);}else if(e&&e->state==FitEvidenceState::Verified&&e->preferredCandidateIndex>0){const auto it=std::find_if(e->candidates.cbegin(),e->candidates.cend(),[e](const auto&c){return c.index==e->preferredCandidateIndex;});if(it!=e->candidates.cend()){const double value=FitCalibrationEvidencePolicy::candidateCorrection(*e,*it);if(m_savedConfirmation&&!m_dirty)text=QStringLiteral("Verified calibration saved: %1 mm. Create / Update the Fit Profile to make this correction available to ManufacturingMesh and Auto Fit.").arg(value,0,'f',3);else if(!m_dirty)text=QStringLiteral("Verified calibration loaded: %1 mm. Create / Update the Fit Profile to make this correction available to ManufacturingMesh and Auto Fit.").arg(value,0,'f',3);}}m_guidance->setText(text);m_guidance->setToolTip(text);}
void FitCalibrationDialog::showSession(const FitCalibrationSession&s,const QString&path){FitCalibrationWorkspace workspace;workspace.identity=FitCalibrationLibrary::manufacturingContextFingerprint(s.process);workspace.displayName=FitCalibrationLibrary::workspaceDisplayName(s.process);workspace.process=s.process;workspace.featureSessions.push_back(s);showWorkspace(workspace,s.sessionIdentity);m_path=path;}
void FitCalibrationDialog::showWorkspace(const FitCalibrationWorkspace&workspace,const QString&preferredSession){m_loading=true;m_workspace=workspace;m_path.clear();m_dirty=false;m_savedConfirmation=false;m_printer->setText(workspace.process.printerIdentity);m_material->setText(workspace.process.materialIdentity);m_profile->setText(workspace.process.profileName);if(workspace.process.hasNozzleDiameter)m_nozzle->setValue(workspace.process.nozzleDiameterMillimetres);if(workspace.process.hasLayerHeight)m_layer->setValue(workspace.process.layerHeightMillimetres);m_compensationNotes->setText(workspace.process.dimensionalCompensationNotes);m_features->clear();int selected=0;for(int i=0;i<workspace.featureSessions.size();++i){const auto&s=workspace.featureSessions[i];m_features->addItem(featureName(s),s.sessionIdentity);if(s.sessionIdentity==preferredSession)selected=i;}m_features->setCurrentIndex(selected);m_loading=false;selectFeature(selected);}
void FitCalibrationDialog::selectFeature(int index){if(m_loading||index<0||index>=m_workspace.featureSessions.size())return;if(m_dirty&&!saveSession()){m_features->setCurrentIndex(m_featureIndex);return;}m_loading=true;m_featureIndex=index;m_session=m_workspace.featureSessions[index];m_orientation->setCurrentIndex(m_orientation->findData(int(m_session.process.actualPrintedOrientation)));m_orientationNotes->setText(m_session.process.orientationNotes);m_tabs->setCurrentIndex(FitCalibrationEvidencePolicy::preferredSessionStage(m_session)==FitCalibrationStage::Fine?1:0);m_loading=false;refresh();}
bool FitCalibrationDialog::openSession(const QString&path){FitCalibrationSession s;QString error;const FitCalibrationWorkspace*selected=m_workspace.featureSessions.isEmpty()?nullptr:&m_workspace;if(!m_library.importSessionIntoWorkspace(path,selected,&s,&error)){QMessageBox::warning(this,"Calibration",error);return false;}refreshLibrary();for(const auto&w:m_library.workspaces())if(w.identity==FitCalibrationLibrary::manufacturingContextFingerprint(s.process)){showWorkspace(w,s.sessionIdentity);return true;}showSession(s,QString());return true;}
void FitCalibrationDialog::newTechnicCalibration()
{
    if(m_dirty&&!saveSession())return;
    if(m_workspace.featureSessions.isEmpty()){QMessageBox::information(this,"Parallel Technic Hole Calibration","Resume the manufacturing workspace that should own this orientation-specific evidence first.");return;}
    readProcess();
    for(const auto&feature:m_workspace.featureSessions){const auto*experiment=feature.hasFineExperiment?&feature.fineExperiment:(feature.hasCoarseExperiment?&feature.coarseExperiment:nullptr);if(experiment&&experiment->featureFamily==QStringLiteral("RoundTechnicPassage")&&feature.process.actualPrintedOrientation==FitPrintedOrientation::FeatureAxisParallelToBuildPlate){QMessageBox::information(this,"Parallel Technic Hole Calibration","This workspace already contains a parallel Technic Hole calibration. Select it in Feature calibration to continue.");return;}}
    const auto definition=RoundTechnicCalibrationArtifact::parallelCoarseDefinition();
    auto&directories=SessionFileDialogDirectoryService::instance();
    QString path=QFileDialog::getSaveFileName(this,"Save Parallel Technic Hole Calibration 3MF",directories.initialFilePath(FileDialogDirectoryCategory::SaveExport,definition.artifactIdentity+QStringLiteral(".3mf")),"3MF models (*.3mf)");
    if(path.isEmpty())return;if(!path.endsWith(QStringLiteral(".3mf"),Qt::CaseInsensitive))path+=QStringLiteral(".3mf");directories.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);
    const auto artifact=RoundTechnicCalibrationArtifact::generate(RoundTechnicCalibrationArtifact::canonicalPrototype(),definition);
    if(!artifact.ok){QMessageBox::warning(this,"Parallel Technic Hole Calibration",artifact.diagnostic);return;}
    ThreeMfWriter::Options options;options.objectName=definition.artifactIdentity;options.partIdentity=definition.artifactIdentity;options.modelColor=QColor("#0055BF");QString error;
    if(!ThreeMfWriter::write(artifact.mesh,path,options,&error)){QMessageBox::warning(this,"Parallel Technic Hole Calibration",error);return;}
    FitCalibrationSession session;session.sessionIdentity=FitCalibrationLibrary::newStableIdentity();session.hasCoarseExperiment=true;session.coarseExperiment=RoundTechnicCalibrationArtifact::observationTemplate(artifact,definition);session.process=m_workspace.featureSessions.front().process;session.process.actualPrintedOrientation=FitPrintedOrientation::FeatureAxisParallelToBuildPlate;session.process.orientationNotes=session.coarseExperiment.process.orientationNotes;session.coarseExperiment.process=session.process;
    if(!m_library.saveSession(&session,&error)){QMessageBox::warning(this,"Parallel Technic Hole Calibration",error);return;}
    auto workspace=m_workspace;workspace.featureSessions.push_back(session);showWorkspace(workspace,session.sessionIdentity);refreshLibrary();
    QMessageBox::information(this,"Parallel Technic Hole Calibration",QStringLiteral("The seven-candidate coarse artifact was added to this manufacturing workspace. Print its broad flat base at 100% scale so every passage axis remains parallel to the build plate. Test candidates 1–7 left to right with a genuine LEGO Technic pin; diameters are 4.80 through 5.40 mm in 0.10 mm steps. Record new physical observations before selecting or verifying a correction."));
}
void FitCalibrationDialog::newStudCalibration(){if(m_dirty&&!saveSession())return;bool accepted=false;const QString choice=QInputDialog::getItem(this,"New Stud Calibration","Calibrate:",{"Stud outside diameter (clutch) first","Stud height (seating) after OD"},0,false,&accepted);if(!accepted)return;readProcess();StandardStudCalibrationArtifactDefinition definition;definition.dimension=choice.startsWith("Stud height")?StandardStudCalibrationDimension::Height:StandardStudCalibrationDimension::Diameter;definition.artifactIdentity=definition.dimension==StandardStudCalibrationDimension::Height?StandardStudCalibrationArtifact::heightArtifactIdentity():StandardStudCalibrationArtifact::diameterArtifactIdentity();int heightSessionIndex=-1;const FitCalibrationExperiment*heightSource=nullptr;if(definition.dimension==StandardStudCalibrationDimension::Height){double verifiedOd=0;bool foundVerifiedOd=false;for(const auto&feature:m_workspace.featureSessions){const auto*experiment=feature.hasFineExperiment?&feature.fineExperiment:(feature.hasCoarseExperiment?&feature.coarseExperiment:nullptr);if(!experiment||experiment->featureFamily!=QStringLiteral("StandardStud")||experiment->correctionDimension!=FitCorrectionDimension::Diameter||experiment->state!=FitEvidenceState::Verified)continue;const auto preferred=std::find_if(experiment->candidates.cbegin(),experiment->candidates.cend(),[&](const auto&candidate){return candidate.index==experiment->preferredCandidateIndex;});if(preferred!=experiment->candidates.cend()){verifiedOd=preferred->diameterCorrectionMillimetres;foundVerifiedOd=true;break;}}if(!foundVerifiedOd){QMessageBox::warning(this,"Stud Height Calibration","Verify Stud OD in this manufacturing workspace before creating a Stud Height experiment.");return;}definition.fixedDiameterCorrectionMillimetres=verifiedOd;for(int i=0;i<m_workspace.featureSessions.size();++i){const auto&feature=m_workspace.featureSessions[i];const auto*experiment=feature.hasFineExperiment?&feature.fineExperiment:(feature.hasCoarseExperiment?&feature.coarseExperiment:nullptr);if(experiment&&experiment->featureFamily==QStringLiteral("StandardStud")&&experiment->correctionDimension==FitCorrectionDimension::Height&&experiment->preferredCandidateIndex>0){heightSessionIndex=i;heightSource=experiment;break;}}QString planningError;if(heightSource&&!StandardStudCalibrationArtifact::heightVerificationDefinition(*heightSource,verifiedOd,&definition,&planningError)){QMessageBox::warning(this,"Stud Height Calibration",planningError);return;}}auto&dirs=SessionFileDialogDirectoryService::instance();QString path=QFileDialog::getSaveFileName(this,"Save Stud Calibration 3MF",dirs.initialFilePath(FileDialogDirectoryCategory::SaveExport,definition.artifactIdentity+".3mf"),"3MF models (*.3mf)");if(path.isEmpty())return;if(!path.endsWith(".3mf",Qt::CaseInsensitive))path+=".3mf";dirs.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);const auto artifact=StandardStudCalibrationArtifact::generate(StandardStudCalibrationArtifact::canonicalPrototype(),definition);if(!artifact.ok){QMessageBox::warning(this,"Stud Calibration",artifact.diagnostic);return;}ThreeMfWriter::Options options;options.objectName=definition.artifactIdentity;options.partIdentity=definition.artifactIdentity;options.modelColor=QColor("#0055BF");QString error;if(!ThreeMfWriter::write(artifact.mesh,path,options,&error)){QMessageBox::warning(this,"Stud Calibration",error);return;}const auto experiment=StandardStudCalibrationArtifact::observationTemplate(artifact,definition);FitCalibrationSession session;if(heightSource){const auto&parent=m_workspace.featureSessions[heightSessionIndex];if(parent.hasCoarseExperiment&&!parent.hasFineExperiment){session=parent;session.hasFineExperiment=true;session.fineExperiment=experiment;session.fineExperiment.process=session.process;}else session=FitCalibrationLibrary::continuationSession(parent,*heightSource,experiment);}else{session.sessionIdentity=FitCalibrationLibrary::newStableIdentity();session.hasCoarseExperiment=true;session.coarseExperiment=experiment;const auto featureOrientation=session.coarseExperiment.process;if(!m_workspace.featureSessions.isEmpty()){session.process=m_workspace.featureSessions.front().process;session.process.actualPrintedOrientation=featureOrientation.actualPrintedOrientation;session.process.orientationNotes=featureOrientation.orientationNotes;}else session.process=featureOrientation;session.coarseExperiment.process=session.process;}if(!m_library.saveSession(&session,&error)){QMessageBox::warning(this,"Stud Calibration",error);return;}auto workspace=m_workspace;if(workspace.featureSessions.isEmpty()){workspace.identity=FitCalibrationLibrary::manufacturingContextFingerprint(session.process);workspace.process=session.process;}if(heightSessionIndex>=0&&session.sessionIdentity==workspace.featureSessions[heightSessionIndex].sessionIdentity)workspace.featureSessions[heightSessionIndex]=session;else workspace.featureSessions.push_back(session);workspace.displayName=FitCalibrationLibrary::workspaceDisplayName(session.process);showWorkspace(workspace,session.sessionIdentity);refreshLibrary();const QString message=definition.dimension==StandardStudCalibrationDimension::Diameter?QStringLiteral("The OD artifact was added to this manufacturing workspace. Test candidates 1–7 left to right with genuine LEGO receiving geometry."):(heightSource?QStringLiteral("The Stud Height verification artifact holds the Verified %1 mm OD fixed and tests heights %2, %3, and %4 mm. Record fresh seating observations before Mark Verified.").arg(4.8+definition.fixedDiameterCorrectionMillimetres,0,'f',2).arg(1.6+definition.centerCorrectionMillimetres-definition.candidateSpacingMillimetres,0,'f',2).arg(1.6+definition.centerCorrectionMillimetres,0,'f',2).arg(1.6+definition.centerCorrectionMillimetres+definition.candidateSpacingMillimetres,0,'f',2):QStringLiteral("The initial height artifact holds the Verified %1 mm OD fixed. Test complete seating, vertical gap, bottoming, and engagement depth.").arg(4.8+definition.fixedDiameterCorrectionMillimetres,0,'f',2));QMessageBox::information(this,"Stud Calibration",message);}
void FitCalibrationDialog::loadSession(){auto&dirs=SessionFileDialogDirectoryService::instance();const auto path=QFileDialog::getOpenFileName(this,"Open Calibration Session",dirs.initialDirectory(FileDialogDirectoryCategory::OpenImport),"Calibration JSON (*.json)");if(path.isEmpty())return;dirs.rememberSelectedFile(FileDialogDirectoryCategory::OpenImport,path);openSession(path);}
bool FitCalibrationDialog::writeSession(const QString&path){QSaveFile f(path);if(!f.open(QIODevice::WriteOnly)||f.write(QJsonDocument(FitCalibrationSessionJson::toJson(m_session)).toJson(QJsonDocument::Indented))<0||!f.commit()){QMessageBox::warning(this,"Calibration","The calibration session could not be saved.");return false;}m_dirty=false;m_savedConfirmation=true;updateGuidance();return true;}
bool FitCalibrationDialog::saveSession(){if(!m_session.hasCoarseExperiment&&!m_session.hasFineExperiment)return false;readProcess();QString error;for(auto&feature:m_workspace.featureSessions)if(!m_library.saveSession(&feature,&error)){QMessageBox::warning(this,"Calibration",error);return false;}if(m_featureIndex>=0&&m_featureIndex<m_workspace.featureSessions.size())m_session=m_workspace.featureSessions[m_featureIndex];m_dirty=false;m_savedConfirmation=true;refreshLibrary();updateGuidance();return true;}
void FitCalibrationDialog::scheduleManagedSave(){if((m_session.hasCoarseExperiment||m_session.hasFineExperiment)&&m_autoSave)m_autoSave->start();}
void FitCalibrationDialog::refreshLibrary(){const QString selected=m_workspace.identity.isEmpty()?FitCalibrationLibrary::manufacturingContextFingerprint(m_session.process):m_workspace.identity;QVector<FitLibraryIssue> issues;const auto available=m_library.workspaces(&issues);m_sessions->clear();for(const auto&item:available)m_sessions->addItem(item.displayName,item.identity);const int index=m_sessions->findData(selected);if(index>=0)m_sessions->setCurrentIndex(index);m_sessions->setToolTip(issues.isEmpty()?QStringLiteral("Managed manufacturing-context workspaces in %1").arg(m_library.storageRoot()):QStringLiteral("%1 managed record(s) could not be loaded. Valid records remain available.").arg(issues.size()));}
void FitCalibrationDialog::resumeManagedSession(){const QString identity=m_sessions->currentData().toString();if(identity.isEmpty())return;for(const auto&workspace:m_library.workspaces())if(workspace.identity==identity){showWorkspace(workspace);return;}QMessageBox::warning(this,"Calibration","The selected calibration workspace is no longer available.");refreshLibrary();}
void FitCalibrationDialog::exportSession(){if(m_session.sessionIdentity.isEmpty()&&!saveSession())return;auto&dirs=SessionFileDialogDirectoryService::instance();const QString path=QFileDialog::getSaveFileName(this,"Export Calibration Session",dirs.initialFilePath(FileDialogDirectoryCategory::SaveExport,m_session.sessionIdentity+"-session.json"),"Calibration JSON (*.json)");if(path.isEmpty())return;dirs.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);QString error;if(!m_library.exportSession(m_session.sessionIdentity,path,&error))QMessageBox::warning(this,"Calibration",error);}
void FitCalibrationDialog::createFitProfile(){readProcess();if(m_dirty&&!saveSession())return;bool accepted=false;const QString suggested=QStringLiteral("%1 / %2 / %3 mm / LEGO Fit").arg(m_session.process.printerIdentity,m_session.process.materialIdentity).arg(m_session.process.nozzleDiameterMillimetres,0,'f',2);const QString name=QInputDialog::getText(this,"Create Fit Profile","Profile name:",QLineEdit::Normal,suggested,&accepted).trimmed();if(!accepted)return;FitProfile profile;QString error;if(!m_library.saveVerifiedWorkspaceProfile(m_workspace,name,&profile,&error)){QMessageBox::warning(this,"Fit Profile",error);return;}QMessageBox::information(this,"Fit Profile",QStringLiteral("Verified Fit Profile '%1' now contains all compatible Verified corrections in this manufacturing workspace. Auto Fit applies only corrections supported by the selected Part's recognized functional geometry.").arg(profile.name));}
void FitCalibrationDialog::addObservation(){auto*e=activeExperiment();auto*t=activeTable();const int row=t->currentRow();if(!e||row<0){QMessageBox::information(this,"Calibration","Select a candidate first.");return;}FitCalibrationObservation o;o.result=FitObservation(m_result->currentData().toInt());o.repeatNumber=m_repeat->value();o.hasMeasuredDiameter=m_measured->value()>0;o.measuredDiameterMillimetres=m_measured->value();o.notes=m_notes->text();o.performedUtc=QDateTime::currentDateTimeUtc();QString error;if(!FitCalibrationEvidencePolicy::addObservation(e,e->candidates[row].index,o,&error))QMessageBox::warning(this,"Calibration",error);else{m_dirty=true;m_savedConfirmation=false;scheduleManagedSave();refresh();}}
void FitCalibrationDialog::selectPreferred(){auto*e=activeExperiment();auto*t=activeTable();const int row=t->currentRow();QString error;if(!e||row<0||!FitCalibrationEvidencePolicy::selectPreferredCandidate(e,row<0||!e?0:e->candidates[row].index,&error))QMessageBox::warning(this,"Calibration",error.isEmpty()?"Select a candidate first.":error);else{m_dirty=true;m_savedConfirmation=false;scheduleManagedSave();refresh();}}
void FitCalibrationDialog::markVerified(){readProcess();auto*e=activeExperiment();QString error;if(!e||e->state==FitEvidenceState::Verified||!FitCalibrationEvidencePolicy::markVerified(e,&error)){if(e&&e->state==FitEvidenceState::Verified)return;QMessageBox::warning(this,"Calibration",error.isEmpty()?"Open the fine-search stage first.":error);}else{m_dirty=true;m_savedConfirmation=false;saveSession();refresh();}}
void FitCalibrationDialog::generateFineSearch()
{
    readProcess();
    const auto* active=activeExperiment();
    if(!active||!active->hasRegenerationPrototype||!FitCalibrationEvidencePolicy::continuationAvailable(*active)){QMessageBox::warning(this,"Calibration","Record sufficient directional evidence or select a preferred candidate first.");return;}
    const FitCalibrationExperiment source=*active;
    if(source.featureFamily==QStringLiteral("FrictionlessTechnicPin")){QMessageBox::information(this,"Frictionless Pin Calibration","Phase 5A records physical evidence directly on the seven-pin coarse artifact. Record both neighboring candidates and repeat the preferred candidate; Mark Verified becomes available when that evidence is sufficient.");return;}
    if(source.featureFamily==QStringLiteral("TechnicAxleHole")){QMessageBox::information(this,"Technic Axle Hole Calibration","Female axle-hole calibration follows a Verified ordinary male axle result so its clearance is measured against fixed reference geometry. No speculative continuation artifact is generated.");return;}
    auto plan=FitCalibrationEvidencePolicy::nextSearchPlan(source);
    const bool extension=plan.boundary!=FitPreferredBoundary::None;
    bool directVerification=false;
    if(!extension){bool accepted=false;const QString choice=QInputDialog::getItem(this,"Calibration Next Step","Continue with:",{QStringLiteral("Direct repeat / verification"),QStringLiteral("Fine Search")},0,false,&accepted);if(!accepted)return;directVerification=choice.startsWith("Direct");if(directVerification)plan=FitCalibrationEvidencePolicy::directVerificationPlan(source);}
    const QString title=extension?QStringLiteral("Extend Search"):(directVerification?QStringLiteral("Direct Verification"):QStringLiteral("Fine Search"));
    bool ok=false;double spacing=plan.candidateSpacingMillimetres;int count=plan.candidateCount;
    if(!directVerification){spacing=QInputDialog::getDouble(this,title,"Candidate spacing (mm):",spacing,.001,1,3,&ok);if(!ok)return;count=QInputDialog::getInt(this,title,"Odd candidate count:",count,3,9,2,&ok);if(!ok)return;}
    const QString suffix=extension?QStringLiteral("-boundary-extension-v2"):(directVerification?QStringLiteral("-direct-verification-v2"):QStringLiteral("-fine-search-v2"));
    const QString identity=QInputDialog::getText(this,title,"Versioned artifact identity:",QLineEdit::Normal,source.artifactIdentity+suffix,&ok).trimmed();if(!ok||identity.isEmpty())return;
    auto&dirs=SessionFileDialogDirectoryService::instance();const QString path=QFileDialog::getSaveFileName(this,QStringLiteral("Save %1 3MF").arg(title),dirs.initialFilePath(FileDialogDirectoryCategory::SaveExport,identity+".3mf"),"3MF models (*.3mf)");if(path.isEmpty())return;dirs.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);
    PrintMesh mesh;FitCalibrationExperiment verification;QString diagnostic;
    if(source.featureFamily==QStringLiteral("StandardStud")){StandardStudCalibrationArtifactDefinition d;d.artifactIdentity=identity;d.parentArtifactIdentity=source.artifactIdentity;d.dimension=source.correctionDimension==FitCorrectionDimension::Height?StandardStudCalibrationDimension::Height:StandardStudCalibrationDimension::Diameter;d.centerCorrectionMillimetres=plan.centerCorrectionMillimetres;d.fixedDiameterCorrectionMillimetres=source.fixedDiameterCorrectionMillimetres;d.candidateSpacingMillimetres=spacing;d.candidateCount=count;const auto artifact=StandardStudCalibrationArtifact::generate(source.regenerationPrototype,d);if(artifact.ok){mesh=artifact.mesh;verification=StandardStudCalibrationArtifact::observationTemplate(artifact,d);}diagnostic=artifact.diagnostic;}
    else if(source.featureFamily==QStringLiteral("StudReceivingClutch")){StudReceivingCalibrationArtifactDefinition d;d.artifactIdentity=identity;d.parentArtifactIdentity=source.artifactIdentity;d.centerDiameterCorrectionMillimetres=plan.centerCorrectionMillimetres;d.candidateSpacingMillimetres=spacing;d.candidateCount=count;const auto artifact=StudReceivingCalibrationArtifact::generate(source.regenerationPrototype,d);if(artifact.ok){mesh=artifact.mesh;verification=StudReceivingCalibrationArtifact::observationTemplate(artifact,d);}diagnostic=artifact.diagnostic;}
    else if(source.featureFamily==QStringLiteral("FrictionTechnicPin")){FrictionTechnicPinCalibrationArtifactDefinition d;d.artifactIdentity=identity;d.parentArtifactIdentity=source.artifactIdentity;d.centerRidgeEnvelopeCorrectionMillimetres=plan.centerCorrectionMillimetres;d.candidateSpacingMillimetres=spacing;d.candidateCount=count;const auto artifact=FrictionTechnicPinCalibrationArtifact::generate(source.regenerationPrototype,d);if(artifact.ok){mesh=artifact.mesh;verification=FrictionTechnicPinCalibrationArtifact::observationTemplate(artifact);}diagnostic=artifact.diagnostic;}
    else if(source.featureFamily==QStringLiteral("TechnicAxle")){TechnicAxleCalibrationArtifactDefinition d;d.artifactIdentity=identity;d.parentArtifactIdentity=source.artifactIdentity;d.centerTipToTipCorrectionMillimetres=plan.centerCorrectionMillimetres;d.candidateSpacingMillimetres=spacing;d.candidateCount=count;const auto artifact=TechnicAxleCalibrationArtifact::generate(source.regenerationPrototype,d);if(artifact.ok){mesh=artifact.mesh;verification=TechnicAxleCalibrationArtifact::observationTemplate(artifact,d);}diagnostic=artifact.diagnostic;}
    else{RoundTechnicCalibrationArtifactDefinition d;d.artifactIdentity=identity;d.parentArtifactIdentity=source.artifactIdentity;d.centerDiameterCorrectionMillimetres=plan.centerCorrectionMillimetres;d.candidateSpacingMillimetres=spacing;d.candidateCount=count;const auto artifact=RoundTechnicCalibrationArtifact::generate(source.regenerationPrototype,d);if(artifact.ok){mesh=artifact.mesh;verification=RoundTechnicCalibrationArtifact::observationTemplate(artifact,d);}diagnostic=artifact.diagnostic;}
    if(mesh.faces.empty()){QMessageBox::warning(this,"Calibration",diagnostic);return;}ThreeMfWriter::Options options;options.objectName=identity;options.partIdentity=identity;options.modelColor=QColor("#0055BF");QString error;if(!ThreeMfWriter::write(mesh,path,options,&error)){QMessageBox::warning(this,"Calibration",error);return;}
    verification.process=m_session.process;
    if(m_tabs->currentIndex()==1){if(m_dirty&&!saveSession())return;m_session=FitCalibrationLibrary::continuationSession(m_session,source,verification);}
    else{m_session.hasFineExperiment=true;m_session.fineExperiment=verification;if(m_session.sessionIdentity.isEmpty())m_session.sessionIdentity=source.artifactIdentity;}
    if(m_featureIndex>=0&&m_featureIndex<m_workspace.featureSessions.size())m_workspace.featureSessions[m_featureIndex]=m_session;
    m_dirty=true;m_savedConfirmation=false;if(!saveSession())return;m_tabs->setCurrentIndex(1);refresh();
    const QString message=extension?(plan.uniformResult!=FitUniformResult::None?QStringLiteral("The uniform physical results established the search direction without a Preferred candidate. The extended coarse artifact overlaps the prior boundary and starts with fresh observations."):QStringLiteral("The preferred candidate was at the search boundary. The extended artifact overlaps that boundary and continues in the required direction; record fresh observations before verification.")):(directVerification?QStringLiteral("The three-candidate verification artifact repeats the selected correction and its immediate neighbors. Record fresh observations, repeat the preferred candidate, then use Mark Verified when the evidence is complete."):QStringLiteral("The optional fine-search artifact is ready with empty evidence for this new print."));
    QMessageBox::information(this,title+QStringLiteral(" Generated"),message);
}

void FitCalibrationDialog::newReceivingClutchCalibration(){if(m_dirty&&!saveSession())return;if(m_workspace.featureSessions.isEmpty()){QMessageBox::information(this,"Receiving Clutch Calibration","Resume or import a manufacturing workspace first so the new evidence inherits its manufacturing context.");return;}auto&dirs=SessionFileDialogDirectoryService::instance();QString path=QFileDialog::getSaveFileName(this,"Save TubeWallCell Calibration 3MF",dirs.initialFilePath(FileDialogDirectoryCategory::SaveExport,StudReceivingCalibrationArtifact::artifactIdentity()+".3mf"),"3MF models (*.3mf)");if(path.isEmpty())return;if(!path.endsWith(".3mf",Qt::CaseInsensitive))path+=".3mf";dirs.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);const auto artifact=StudReceivingCalibrationArtifact::generate();if(!artifact.ok){QMessageBox::warning(this,"Receiving Clutch Calibration",artifact.diagnostic);return;}ThreeMfWriter::Options options;options.objectName=artifact.artifactIdentity;options.partIdentity=artifact.artifactIdentity;options.modelColor=QColor("#0055BF");QString error;if(!ThreeMfWriter::write(artifact.mesh,path,options,&error)){QMessageBox::warning(this,"Receiving Clutch Calibration",error);return;}auto experiment=StudReceivingCalibrationArtifact::observationTemplate(artifact);FitCalibrationSession session;session.sessionIdentity=FitCalibrationLibrary::newStableIdentity();session.process=m_workspace.process;session.process.actualPrintedOrientation=experiment.process.actualPrintedOrientation;session.process.orientationNotes=experiment.process.orientationNotes;session.hasCoarseExperiment=true;session.coarseExperiment=experiment;session.coarseExperiment.process=session.process;if(!m_library.saveSession(&session,&error)){QMessageBox::warning(this,"Receiving Clutch Calibration",error);return;}auto workspace=m_workspace;workspace.featureSessions.push_back(session);showWorkspace(workspace,session.sessionIdentity);refreshLibrary();QMessageBox::information(this,"Receiving Clutch Calibration","The seven-cell TubeWallCell artifact was added to this manufacturing workspace. Test candidates left to right with a genuine LEGO stud in the normal tube-and-wall receiving position, not in the center bore.");}

void FitCalibrationDialog::newFrictionPinCalibration(){if(m_dirty&&!saveSession())return;if(m_workspace.featureSessions.isEmpty()){QMessageBox::information(this,"Friction Pin Calibration","Resume or import a manufacturing workspace first so the new evidence inherits its manufacturing context.");return;}auto&dirs=SessionFileDialogDirectoryService::instance();QString path=QFileDialog::getSaveFileName(this,"Save Friction Technic Pin Calibration 3MF",dirs.initialFilePath(FileDialogDirectoryCategory::SaveExport,FrictionTechnicPinCalibrationArtifact::artifactIdentity()+".3mf"),"3MF models (*.3mf)");if(path.isEmpty())return;if(!path.endsWith(".3mf",Qt::CaseInsensitive))path+=".3mf";dirs.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);const auto artifact=FrictionTechnicPinCalibrationArtifact::generate();if(!artifact.ok){QMessageBox::warning(this,"Friction Pin Calibration",artifact.diagnostic);return;}ThreeMfWriter::Options options;options.objectName=artifact.artifactIdentity;options.partIdentity=artifact.artifactIdentity;options.modelColor=QColor("#A0A5A9");QString error;if(!ThreeMfWriter::write(artifact.mesh,path,options,&error)){QMessageBox::warning(this,"Friction Pin Calibration",error);return;}auto experiment=FrictionTechnicPinCalibrationArtifact::observationTemplate(artifact);FitCalibrationSession session;session.sessionIdentity=FitCalibrationLibrary::newStableIdentity();session.process=m_workspace.process;session.process.actualPrintedOrientation=experiment.process.actualPrintedOrientation;session.process.orientationNotes=experiment.process.orientationNotes;session.hasCoarseExperiment=true;session.coarseExperiment=experiment;session.coarseExperiment.process=session.process;if(!m_library.saveSession(&session,&error)){QMessageBox::warning(this,"Friction Pin Calibration",error);return;}auto workspace=m_workspace;workspace.featureSessions.push_back(session);showWorkspace(workspace,session.sessionIdentity);refreshLibrary();QMessageBox::information(this,"Friction Pin Calibration","The seven-candidate rib-envelope artifact was added to this manufacturing workspace. Candidate #1 is beside the raised marker. Print at 100%, then test each candidate using two genuine LEGO Technic receiving Parts for insertion, retention, play, removal force, deformation, and repeatability.");}
void FitCalibrationDialog::newFrictionlessPinCalibration(){if(m_dirty&&!saveSession())return;if(m_workspace.featureSessions.isEmpty()){QMessageBox::information(this,"Frictionless Pin Calibration","Resume or import a manufacturing workspace first so the new evidence inherits its manufacturing context.");return;}auto&dirs=SessionFileDialogDirectoryService::instance();QString path=QFileDialog::getSaveFileName(this,"Save Frictionless Technic Pin Calibration 3MF",dirs.initialFilePath(FileDialogDirectoryCategory::SaveExport,FrictionlessTechnicPinCalibrationArtifact::artifactIdentity()+".3mf"),"3MF models (*.3mf)");if(path.isEmpty())return;if(!path.endsWith(".3mf",Qt::CaseInsensitive))path+=".3mf";dirs.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);const auto artifact=FrictionlessTechnicPinCalibrationArtifact::generate();if(!artifact.ok){QMessageBox::warning(this,"Frictionless Pin Calibration",artifact.diagnostic);return;}ThreeMfWriter::Options options;options.objectName=artifact.artifactIdentity;options.partIdentity=artifact.artifactIdentity;options.modelColor=QColor("#A0A5A9");QString error;if(!ThreeMfWriter::write(artifact.mesh,path,options,&error)){QMessageBox::warning(this,"Frictionless Pin Calibration",error);return;}auto experiment=FrictionlessTechnicPinCalibrationArtifact::observationTemplate(artifact);FitCalibrationSession session;session.sessionIdentity=FitCalibrationLibrary::newStableIdentity();session.process=m_workspace.process;session.process.actualPrintedOrientation=experiment.process.actualPrintedOrientation;session.process.orientationNotes=experiment.process.orientationNotes;session.hasCoarseExperiment=true;session.coarseExperiment=experiment;session.coarseExperiment.process=session.process;if(!m_library.saveSession(&session,&error)){QMessageBox::warning(this,"Frictionless Pin Calibration",error);return;}auto workspace=m_workspace;workspace.featureSessions.push_back(session);showWorkspace(workspace,session.sessionIdentity);refreshLibrary();QMessageBox::information(this,"Frictionless Pin Calibration","The seven-pin artifact was added to this manufacturing workspace. Print at 100%, then test candidates left to right in the same genuine LEGO Technic hole for insertion, engagement, retention, play, removal, deformation, and repeatability.");}

void FitCalibrationDialog::newTechnicAxleCalibration(){if(m_dirty&&!saveSession())return;if(m_workspace.featureSessions.isEmpty()){QMessageBox::information(this,"Technic Axle Calibration","Resume or import a manufacturing workspace first so the new evidence inherits its manufacturing context.");return;}auto&dirs=SessionFileDialogDirectoryService::instance();QString path=QFileDialog::getSaveFileName(this,"Save Technic Axle Calibration 3MF",dirs.initialFilePath(FileDialogDirectoryCategory::SaveExport,TechnicAxleCalibrationArtifact::artifactIdentity()+".3mf"),"3MF models (*.3mf)");if(path.isEmpty())return;if(!path.endsWith(".3mf",Qt::CaseInsensitive))path+=".3mf";dirs.rememberSelectedFile(FileDialogDirectoryCategory::SaveExport,path);const auto artifact=TechnicAxleCalibrationArtifact::generate();if(!artifact.ok){QMessageBox::warning(this,"Technic Axle Calibration",artifact.diagnostic);return;}ThreeMfWriter::Options options;options.objectName=artifact.artifactIdentity;options.partIdentity=artifact.artifactIdentity;options.modelColor=QColor("#A0A5A9");QString error;if(!ThreeMfWriter::write(artifact.mesh,path,options,&error)){QMessageBox::warning(this,"Technic Axle Calibration",error);return;}auto experiment=TechnicAxleCalibrationArtifact::observationTemplate(artifact);FitCalibrationSession session;session.sessionIdentity=FitCalibrationLibrary::newStableIdentity();session.process=m_workspace.process;session.process.actualPrintedOrientation=experiment.process.actualPrintedOrientation;session.process.orientationNotes=experiment.process.orientationNotes;session.hasCoarseExperiment=true;session.coarseExperiment=experiment;session.coarseExperiment.process=session.process;if(!m_library.saveSession(&session,&error)){QMessageBox::warning(this,"Technic Axle Calibration",error);return;}auto workspace=m_workspace;workspace.featureSessions.push_back(session);showWorkspace(workspace,session.sessionIdentity);refreshLibrary();QMessageBox::information(this,"Technic Axle Calibration","The seven-candidate ordinary axle artifact was added to this manufacturing workspace. Candidate #1 is beside the raised marker. Print at 100%, then test each candidate in ordinary genuine LEGO axle holes such as Parts 11478 and 10095. Record insertion, rotational play, retention, removal, visible stress, and repeatability; do not use reduced, rounded, or sliding axle-hole variants.");}

void FitCalibrationDialog::newTechnicAxleHoleCalibration(){QMessageBox::information(this,"Technic Axle Hole Calibration","Calibrate the ordinary male Technic Axle first against genuine LEGO axle holes. Female axle-hole evidence will use a fixed Verified male reference so the two corrections remain independently attributable. Phase 6A does not generate speculative female evidence before that dependency exists.");}
